  async function startToolJob(endpoint,config,kind){if(state.busy||state.uploadBusy){toast('Wait for the current job or cancel it first.');return;}try{if(!config.source_path||!config.output_dir)throw new Error('Choose a source movie and an output folder.');state.activeKind=kind;state.busy=true;setJobButtons();$('error-banner').hidden=true;const result=await api(endpoint,config);state.jobId=result.id;state.reportKey='';state.lastLog='';pollJob();}catch(error){state.busy=false;setJobButtons();showError(error);}}
  function updateToolProgress(job){for(const host of $$('[data-tool-status]')){host.hidden=false;host.replaceChildren();const heading=textEl('div','','section-heading');heading.append(textEl('h2',`${job.kind==='clip'?'Highlight':job.kind==='effects'?'Effects':'Edit'} · ${job.status}`));if(['queued','running'].includes(job.status)){const cancel=textEl('button','Cancel','danger small');cancel.type='button';cancel.addEventListener('click',async()=>{cancel.disabled=true;try{await api(`/api/jobs/${encodeURIComponent(job.id)}/cancel`,{});pollJob();}catch(error){showError(error);}});heading.append(cancel);}host.append(heading,textEl('p',job.error||job.stage||'','help'));const logs=textEl('pre',(job.logs||[]).slice(-12).join('\n'),'tool-logs');host.append(logs);}}
  function renderToolResult(job){const effects=job.kind==='effects',host=$(effects?'effects-result':'highlight-result');host.hidden=false;host.replaceChildren();const report=job.report||{},video=(job.artifacts||[]).find(a=>a.kind==='video');host.append(textEl('h3',job.config?.preview?'Preview ready':'Export ready'));if(report.outputs?.video)host.append(textEl('p',report.outputs.video,'help result-path'));const downloads=textEl('div','','downloads');for(const artifact of job.artifacts||[]){const link=textEl('a',`↓ ${artifact.kind==='video'?'Download video':artifact.name}`);link.href=artifact.url;link.download=artifact.name;downloads.append(link);}host.append(downloads);if(video){if(effects){$('effects-video').src=video.url;$('effects-video').hidden=false;$('effects-empty').hidden=true;}else{const player=document.createElement('video');player.src=video.url;player.controls=true;player.preload='metadata';player.className='highlight-video';host.append(player);const send=textEl('button','Use this exported clip in Effects →','small');send.type='button';send.addEventListener('click',()=>{$('effects-source').value=report.outputs?.video||job.config?.output_path||'';$('effects-start').value=0;$('effects-end').value='';selectPage('effects');});host.append(send);}}}
