  function dependencyAvailable(value){if(value===null||value===undefined||value===false)return false;if(typeof value==='object'){if('available' in value)return !!value.available;if('ok' in value)return !!value.ok;}return !!value;}
  async function fetchSetup(){const data=await api('/api/setup');setupState.data=data;state.config={...(state.config||{}),default_folder:data.default_folder,default_output:data.default_output,dependencies:data.dependencies,setup_completed:data.completed,can_render:data.can_render};return data;}
  async function openSetup(firstRun=false){setupState.loading=true;setupState.firstRun=firstRun;setupState.step=firstRun?0:1;$('setup-error').hidden=true;$('setup-save-status').textContent='';$('setup-title').textContent=firstRun?'Welcome to your studio.':'Studio settings';$('setup-description').textContent=firstRun?'A few quick choices, then you’re ready to start.':'Default folders, editing tools, and help when you need it.';if(!$('setup-dialog').open)$('setup-dialog').showModal();renderSetupStep();try{const data=await fetchSetup();$('setup-default-folder').value=data.default_folder||'';$('setup-default-output').value=data.default_output||'';renderRuntime(data);setJobButtons();}catch(error){setupError(error);}finally{setupState.loading=false;renderSetupStep();}}
