  function renderRuntime(data){const host=$('runtime-checks');host.replaceChildren();const labels={ffmpeg:'Video rendering',ffprobe:'Media inspection',numpy:'Audio analysis',scipy:'Audio matching'};let allReady=true;for(const [key,label]of Object.entries(labels)){const value=data.dependencies?.[key],ok=dependencyAvailable(value);allReady=allReady&&ok;const row=textEl('div','','runtime-row');row.dataset.ready=String(ok);const icon=textEl('span',ok?'✓':'!','runtime-icon');icon.setAttribute('aria-hidden','true');const name=textEl('div',label);name.append(textEl('small',key==='ffmpeg'?'Encode your final video':key==='ffprobe'?'Read recording formats and timing':key==='numpy'?'Compare camera and master audio':'Find offsets and clock drift'));row.append(icon,name,textEl('span',ok?'Ready':'Unavailable','runtime-result'));host.append(row);}const ready=typeof data.can_render==='boolean'?data.can_render:allReady;setupState.data={...data,can_render:ready};$('runtime-summary').textContent=ready?'Everything needed to process your recordings is available.':'Some editing tools are unavailable. Your files and settings are safe.';$('runtime-help').hidden=ready;$('dependency-warning').hidden=ready;if(!ready)$('dependency-warning').textContent='Some editing tools are unavailable. Open Settings to check the app before rendering.';setJobButtons();const arch=data.architecture==='arm64'?'Apple silicon':data.architecture==='x86_64'?'Intel':data.architecture||'';$('runtime-machine').textContent=[data.version?`Multicam Studio ${data.version}`:'',data.platform==='Darwin'?'macOS':data.platform||'',arch].filter(Boolean).join(' · ');renderSetupStep();}
