  $('setup-next').addEventListener('click',async()=>{if(setupState.loading||setupState.saving)return;const step=setupState.step;$('setup-error').hidden=true;if(step===0){setupState.step=1;renderSetupStep();$('setup-default-folder').focus();return;}if(step===3){$('setup-dialog').close();toast('Studio preferences saved. Add your recordings to start.');return;}if(step===2){if(setupState.data?.can_render){setupState.step=setupState.data.completed?3:1;renderSetupStep();}return;}const default_folder=$('setup-default-folder').value.trim(),default_output=$('setup-default-output').value.trim();if(!default_folder||!default_output){setupError('Choose both a recordings folder and an export folder.');return;}setupState.saving=true;$('setup-save-status').textContent='Checking folders…';renderSetupStep();try{const oldOutput=state.config?.default_output;await api('/api/setup',{default_folder,default_output});const data=await fetchSetup();for(const id of ['output-dir','highlight-output','effects-output'])if(!$(id).value||$(id).value===oldOutput)$(id).value=data.default_output;$('setup-save-status').textContent='Preferences saved.';setupState.step=2;renderRuntime(data);scheduleAutosave();}catch(error){setupError(error);$('setup-save-status').textContent='';if(setupState.data?.can_render===false){setupState.step=2;renderRuntime(setupState.data);}}finally{setupState.saving=false;renderSetupStep();}});
